# Account lifecycle (legacy).
ACTIVE, SUSPENDED, CLOSED = "ACTIVE", "SUSPENDED", "CLOSED"


def next_status(status, missed_payments, days_suspended):
    if status == ACTIVE and missed_payments >= 3:
        return SUSPENDED
    if status == SUSPENDED and missed_payments == 0:
        return ACTIVE
    if status == SUSPENDED and days_suspended >= 90:
        return CLOSED
    return status
